def transform(grid):
    from collections import Counter, deque

    h, w = len(grid), len(grid[0])
    bg = Counter(x for row in grid for x in row).most_common(1)[0][0]
    out = [row[:] for row in grid]
    seen = set()

    for r in range(h):
        for c in range(w):
            if grid[r][c] == bg or (r, c) in seen:
                continue

            color = grid[r][c]
            q = deque([(r, c)])
            seen.add((r, c))
            cells = []
            while q:
                y, x = q.popleft()
                cells.append((y, x))
                for dy, dx in ((1, 0), (-1, 0), (0, 1), (0, -1)):
                    ny, nx = y + dy, x + dx
                    if (0 <= ny < h and 0 <= nx < w and
                            (ny, nx) not in seen and grid[ny][nx] == color):
                        seen.add((ny, nx))
                        q.append((ny, nx))

            y0 = min(y for y, x in cells)
            y1 = max(y for y, x in cells)
            x0 = min(x for y, x in cells)
            x1 = max(x for y, x in cells)
            if y1 - y0 < 2 or x1 - x0 < 2:
                continue

            border = all(
                grid[y][x] == color
                for y in range(y0, y1 + 1)
                for x in range(x0, x1 + 1)
                if y in (y0, y1) or x in (x0, x1)
            )
            if border:
                fill = 2 if (y1 - y0 + 1) % 2 == 0 else 7
                for y in range(y0 + 1, y1):
                    for x in range(x0 + 1, x1):
                        out[y][x] = fill

    return out
